            page.on("requestfailed", lambda r: errors.append("reqfail:" + r.url))
            await page.goto(HTML)
            await page.screenshot(path=f"shot_{name}_fold.png")
            await page.screenshot(path=f"shot_{name}_full.png", full_page=True)
            data = await page.evaluate(CHECK_JS)
            print(f"=== {name} ===")
            print("scrollW", data["scrollW"], "innerW", data["innerW"], "errors", errors)
            print("cta", data["ctaRect"], "radius", data["ctaRadius"])
            print("main", data["mainRect"])
            print("logo", data["logoRect"])
            for t in data["texts"]:
                first = t["ff"].split(",")[0].strip().strip('"').strip("'")
                expect = "Noto Sans SC" if t["tag"] in ("H1","H2","H3","H4","H5","H6") else "Noto Serif SC"
                flag = "OK" if first == expect else "FONT-MISMATCH"
                print(f"{flag} {t['tag']} '{t['text']}' first={first} size={t['size']} color={t['color']} top={round(t['rect']['y'])} bottom={round(t['rect']['y']+t['rect']['height'])}")
            await ctx.close()
        await browser.close()

asyncio.run(main())


